package ai.decisionos.aside;
import android.app.*;import android.net.Uri;import android.os.*;import android.graphics.*;import android.graphics.pdf.PdfRenderer;import android.widget.*;import android.view.*;
/** Read-only in-app PDF pages; one rendered bitmap at a time. */
final class CampusPdfPreview {
 static void show(Activity a,Uri uri){try{ParcelFileDescriptor file=a.getContentResolver().openFileDescriptor(uri,"r");PdfRenderer pdf=new PdfRenderer(file);Dialog dialog=new Dialog(a);LinearLayout root=new LinearLayout(a);root.setOrientation(1);root.setPadding(18,18,18,18);root.setBackgroundColor(Color.WHITE);LinearLayout controls=new LinearLayout(a);Button previous=new Button(a),next=new Button(a),close=new Button(a);previous.setText("이전");next.setText("다음");close.setText("닫기");controls.addView(previous);controls.addView(next);controls.addView(close);TextView title=new TextView(a);title.setTextColor(NubiCompanionUi.INK);root.addView(title);root.addView(controls);ScrollView scroll=new ScrollView(a);ImageView image=new ImageView(a);image.setAdjustViewBounds(true);image.setScaleType(ImageView.ScaleType.FIT_CENTER);scroll.addView(image,new ScrollView.LayoutParams(-1,-2));root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));int[] index={0};Bitmap[] bitmap={null};Runnable draw=()->{try(PdfRenderer.Page page=pdf.openPage(index[0])){int width=Math.min(1400,Math.max(720,a.getResources().getDisplayMetrics().widthPixels));Bitmap b=Bitmap.createBitmap(width,Math.max(1,(int)((long)width*page.getHeight()/page.getWidth())),Bitmap.Config.ARGB_8888);b.eraseColor(Color.WHITE);page.render(b,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);image.setImageBitmap(b);if(bitmap[0]!=null)bitmap[0].recycle();bitmap[0]=b;title.setText((index[0]+1)+" / "+pdf.getPageCount()+"쪽 · 원문·번역 대조");previous.setEnabled(index[0]>0);next.setEnabled(index[0]+1<pdf.getPageCount());scroll.scrollTo(0,0);}};previous.setOnClickListener(v->{index[0]--;draw.run();});next.setOnClickListener(v->{index[0]++;draw.run();});close.setOnClickListener(v->dialog.dismiss());dialog.setContentView(root);dialog.setOnDismissListener(d->{image.setImageDrawable(null);if(bitmap[0]!=null)bitmap[0].recycle();pdf.close();try{file.close();}catch(Exception ignored){}});dialog.show();dialog.getWindow().setLayout(-1,-1);draw.run();}catch(Exception e){new AlertDialog.Builder(a).setTitle("PDF 확인 필요").setMessage("PDF 페이지를 열지 못했어요. 파일과 다운로드 결과를 확인해 주세요.").setPositiveButton("확인",null).show();}}
}
